import{_ as i,I as r,o as d,c as o,ak as s,J as t}from"./chunks/framework.CYL5YPWS.js";const m=JSON.parse('{"title":"Media","description":"","frontmatter":{},"headers":[],"relativePath":"grindr-api/media/index.md","filePath":"grindr-api/media/index.md"}'),n={name:"grindr-api/media/index.md"};function c(h,e,l,p,g,u){const a=r("Subpages");return d(),o("div",null,[e[0]||(e[0]=s('<h1 id="media" tabindex="-1">Media <a class="header-anchor" href="#media" aria-label="Permalink to “Media”">​</a></h1><p>Media files in Grindr are stored on cdns.grindr.com:443 hosted by Amazon CloudFront powered by AmazonS3. All CDN files are accessible without <a href="/grindr-api/api-authorization">authorization</a> but some are protected with signed URLs. No <a href="/grindr-api/security-headers">security headers</a> or <code>Authorization</code> need to be present in a request to CDN.</p><p>Caching is supported via <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/ETag" target="_blank" rel="noreferrer">ETag header</a> — MD5 hash of image file. Image files might have <code>image/jpeg</code>, <code>image/png</code> or <code>image/webp</code> type, based on original.</p><p>Media files are identified by either a 40-character (public files) or 64-character (signed files) hexadecimal string. Although not confirmed for all types of media, it appears to be SHA-1 hash for 40-character hash and SHA-256 hash for 64-character hash. Confirmed cases: <a href="/grindr-api/messaging/messages#audiomessagebody">Audio</a> uses SHA-256 for its 64-character mediaHash.</p><h2 id="cdn-request-headers" tabindex="-1">CDN request headers <a class="header-anchor" href="#cdn-request-headers" aria-label="Permalink to “CDN request headers”">​</a></h2><p>The official app sends <code>Accept: image/webp,image/*;q=0.8</code> and the same <a href="/grindr-api/security-headers#user-agent">User-Agent</a> as the API, plus <code>Accept-Encoding: gzip</code> unless the request carries a <code>Range</code>. Same <a href="/grindr-api/security-headers">TLS and HTTP/2 fingerprint</a>. No <code>Authorization</code>, no <code>L-*</code> headers, no cookies.</p><p>Signed URLs rotate their <code>Signature</code> on every fetch while the rest of the URL stays stable, so cache on the URL without its query.</p><p>Album videos are played with <code>android.media.MediaPlayer</code> User-Agent:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Dalvik/&lt;vmVersion&gt; (Linux; U; Android &lt;os&gt;; &lt;deviceModel&gt; Build/&lt;buildId&gt;)</span></span></code></pre></div><ul><li><code>vmVersion</code>: ART version, <code>2.1.0</code> on every current release</li><li><code>os</code>, <code>deviceModel</code>: same values as the app <a href="/grindr-api/security-headers#user-agent">User-Agent</a></li><li><code>buildId</code>: <code>Build.ID</code> of that exact OS build, e.g. <code>UQ1A.240105.004</code> — device- and patch-specific, with no counterpart in any Grindr header</li></ul><p>Example: <code>Dalvik/2.1.0 (Linux; U; Android 14; Pixel 8 Build/UQ1A.240105.004)</code></p><p>Its first request carries no <code>Range</code>; seeking re-requests with an open-ended <code>Range: bytes=&lt;offset&gt;-</code>.</p><p>There are two types of files stored on CDN.</p>',13)),t(a)])}const b=i(n,[["render",c]]);export{m as __pageData,b as default};
